  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — is it to maximize total profit (unit price minus raw material cost, minus the operating costs of the equipment used), or to maximize total revenue, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

